def dependencies(nodes):
    graph = {node["id"]: list(dict.fromkeys(node.get("needs", []))) for node in nodes}
    if len(graph) != len(nodes):
        raise ValueError("duplicate node")
    for needs in graph.values():
        if any(dep not in graph for dep in needs):
            raise ValueError("unknown dependency")
    return graph

def order(graph):
    # Kahn's algorithm with lexicographic tie‑break
    in_deg = {n: 0 for n in graph}
    for deps in graph.values():
        for d in deps:
            in_deg[d] += 1
    ready = sorted([n for n, d in in_deg.items() if d == 0])
    result = []
    while ready:
        node = ready.pop(0)  # smallest
        result.append(node)
        for succ in graph:
            if node in graph[succ]:
                in_deg[succ] -= 1
                if in_deg[succ] == 0:
                    ready.append(succ)
        ready.sort()
    if len(result) != len(graph):
        raise ValueError("cycle detected")
    return result

