def order(graph):
    pending, result = set(graph), []
    while pending:
        ready = sorted(node for node in pending if all(dep in result for dep in graph[node]))
        if not ready:
            return result + sorted(pending)
        current = ready[-1]
        result.append(current)
        pending.remove(current)
